-- Rollback of the PE OCR J587 remap: restores the AQA 8582 state.
update subjects set exam_board = 'AQA', spec_code = '8582' where name = 'Physical Education';
update questions set active = true, subtopic_id = null where topic_id in (select id from topics where subject_id = (select id from subjects where name = 'Physical Education'));
update topics set name = 'The Musculoskeletal System', spec_ref = '3.1.1.1', paper = 'Paper 1' where id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 1);
update subtopics st set name = v.old_name, spec_ref = v.ref, display_order = v.ord from (values ('Major bones and functions of the skeleton', 'Functions of the skeleton', '3.1.1.1', 1), ('Synovial joints, ligaments, cartilage and tendons', 'Bones and types of synovial joint', '3.1.1.1', 2), ('Movement at hinge and ball and socket joints', 'Movement at joints', '3.1.1.1', 3), ('Major muscle groups and the roles of muscles', 'Voluntary muscles and antagonistic pairs', '3.1.1.1', 4)) as v(cur_name, old_name, ref, ord) where st.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 1) and st.name = v.cur_name;
update topics set name = 'The Cardio-Respiratory System & Aerobic/Anaerobic Exercise', spec_ref = '3.1.1.2-3.1.1.4', paper = 'Paper 1' where id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 2);
update subtopics st set name = v.old_name, spec_ref = v.ref, display_order = v.ord from (values ('The heart, blood and double circulation', 'Structure of the heart and cardiac cycle', '3.1.1.2', 1), ('Blood vessels: arteries, veins and capillaries', 'Blood vessels: arteries, veins and capillaries', '3.1.1.2', 2), ('The respiratory system and gas exchange', 'The respiratory system and gas exchange', '3.1.1.2', 3), ('Aerobic and anaerobic exercise', 'Aerobic exercise and its effects', '3.1.1.3', 4), ('Short- and long-term effects of exercise', 'Anaerobic exercise, lactic acid and EPOC', '3.1.1.3', 5)) as v(cur_name, old_name, ref, ord) where st.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 2) and st.name = v.cur_name;
update topics set name = 'Movement Analysis: Levers, Planes & Axes', spec_ref = '3.1.2', paper = 'Paper 1' where id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 3);
update subtopics st set name = v.old_name, spec_ref = v.ref, display_order = v.ord from (values ('Lever systems: first, second and third class', 'Lever systems: first, second and third class', '3.2.1', 1), ('Mechanical advantage', 'Mechanical advantage', '3.2.1', 2), ('Planes of movement', 'Planes of movement', '3.2.2', 3), ('Axes of rotation', 'Axes of rotation', '3.2.2', 4)) as v(cur_name, old_name, ref, ord) where st.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 3) and st.name = v.cur_name;
update topics set name = 'Components of Fitness & Fitness Testing', spec_ref = '3.1.3.1-3.1.3.2', paper = 'Paper 1' where id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 4);
update subtopics st set name = v.old_name, spec_ref = v.ref, display_order = v.ord from (values ('Components of fitness', 'Health-related components of fitness', '3.3.2', 1), ('Applying components of fitness to sport', 'Skill-related components of fitness', '3.3.2', 2), ('Fitness tests for each component', 'Fitness tests and protocols', '3.3.2', 3)) as v(cur_name, old_name, ref, ord) where st.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 4) and st.name = v.cur_name;
insert into subtopics (topic_id, name, spec_ref, display_order) select (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 4), 'Interpreting fitness test data', '3.3.2', 4 where not exists (select 1 from subtopics where topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 4) and name = 'Interpreting fitness test data');
update topics set name = 'Principles of Training, Optimising Performance & Injury Prevention', spec_ref = '3.1.3.3-3.1.3.5', paper = 'Paper 1' where id = (select id from topics where subject_id = (select id from subjects where name = 'Physical Education') and display_order = 5);
